steps.codeExample:
static void cobrar(double valor) {
  if (valor <= 0) throw new IllegalArgumentException("Valor inválido");
}
try {
  cobrar(-5);
} catch (IllegalArgumentException e) {
  System.out.println("Ops: " + e.getMessage());
}

